insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-103', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'A true chemical equilibrium can be approached', '["from either the reactant side or the product side","only by starting with pure reactants","only by starting with pure products","only after a catalyst is added"]'::jsonb, 0, 'The same equilibrium state is reached whether one begins with reactants or with products, at a given temperature.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
