insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-104', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'A necessary condition for a chemical equilibrium to be set up is that the reacting system remains', '["closed","open to the air","continuously stirred with fresh feed","at a pressure of 1 atm only"]'::jsonb, 0, 'Matter must not leave or enter; otherwise concentrations never settle to a true equilibrium.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
