insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-105', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'At chemical equilibrium the colour, density and other bulk properties of the mixture', '["stay unchanged with time","oscillate periodically","drift slowly toward the products","become identical to those of the pure reactant"]'::jsonb, 0, 'Macroscopic properties are constant at equilibrium even though molecules still react microscopically.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
