insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-106', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The dynamic character of chemical equilibrium is shown by the observation that', '["forward and reverse reactions continue at equal speeds","all molecular motion stops","only the forward reaction survives","the reaction quotient becomes undefined"]'::jsonb, 0, 'Isotopic tracing shows both directions remain active; their rates are equal, so composition is steady.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
