insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-107', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'Introducing a catalyst into a gaseous mixture that is already at equilibrium', '["leaves the equilibrium composition unaltered","raises the equilibrium constant","shifts the mixture toward products","destroys the reverse reaction"]'::jsonb, 0, 'A catalyst speeds both directions equally. K and the equilibrium amounts stay the same; only the time to reach equilibrium falls.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
