insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-108', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The numerical size of an equilibrium constant informs us about', '["how far the reaction proceeds, not how rapidly it occurs","the activation energy alone","the order of the reaction","the molecularity of the slow step"]'::jsonb, 0, 'K measures the extent of reaction at equilibrium. Rate is a kinetic quantity and is not given by K.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
