insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-109', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For a reaction at chemical equilibrium at constant temperature and pressure, the change in Gibbs energy $\Delta G$ is', '["zero","always negative","always positive","equal to $\\Delta G^\\circ$"]'::jsonb, 0, 'Equilibrium is the state of minimum G at given T and P, so $\Delta G = 0$. $\Delta G^\circ$ is related to K and need not be zero.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
