insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-110', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'A sealed flask holds N2, H2 and NH3 already at equilibrium. Ammonia molecules in that flask', '["keep forming and decomposing at equal rates","stop forming completely","are converted entirely back into N2 and H2","increase steadily because the vessel is closed"]'::jsonb, 0, 'Closure keeps the total amounts fixed, but the Haber reactions remain active in both directions at matching rates.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
