insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-111', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'According to the law of mass action, $K_c$ for $a\mathrm{A} + b\mathrm{B} \rightleftharpoons c\mathrm{C} + d\mathrm{D}$ is', '["$[\\mathrm{C}]^c[\\mathrm{D}]^d / [\\mathrm{A}]^a[\\mathrm{B}]^b$","$[\\mathrm{A}]^a[\\mathrm{B}]^b / [\\mathrm{C}]^c[\\mathrm{D}]^d$","$[\\mathrm{C}][\\mathrm{D}] / [\\mathrm{A}][\\mathrm{B}]$","$a[\\mathrm{A}] + b[\\mathrm{B}]$"]'::jsonb, 0, 'Kc is the quotient of product active masses over reactant active masses, each raised to its stoichiometric coefficient.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
