insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-112', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The standard relation connecting $K_p$ and $K_c$ for a gas reaction is', '["$K_p = K_c(RT)^{\\Delta n}$","$K_p = K_c + RT$","$K_p = K_c / \\Delta n$","$K_p = K_c^{\\Delta n}$"]'::jsonb, 0, 'Partial pressures and concentrations are linked by $p = CRT$, which produces the factor $(RT)^{\Delta n}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
