insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-113', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'In $K_p = K_c(RT)^{\Delta n}$, the exponent $\Delta n$ is', '["gaseous moles of products minus gaseous moles of reactants","total moles of all species including solids","the change in oxidation number","the molecularity of the forward step"]'::jsonb, 0, 'Only gaseous species contribute to $\Delta n$ because Kp is built from partial pressures.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
